/* StockMate local prototype. Demo clock: 02/11/2026, Asia/Ho_Chi_Minh.
 * No backend authentication or real AI is connected. All data stays in this browser. */
(() => {
'use strict';
const KEY='stockmate-prototype-v1', TODAY='2026-11-02', START='2026-10-03', END='2026-11-01';
const $=s=>document.querySelector(s), esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=n=>new Intl.NumberFormat('vi-VN',{style:'currency',currency:'VND',maximumFractionDigits:0}).format(n);
const num=n=>n==null?'—':new Intl.NumberFormat('vi-VN',{maximumFractionDigits:2}).format(n);
const A=window.StockMateAuth, AV=window.StockMateAccountViews;
const roles={admin:'Admin',staff:'Nhân viên kho',planner:'Inventory Planner',manager:'Quản lý'};
const labels={Draft:'Bản nháp',Pending:'Chờ duyệt',Approved:'Đã duyệt',Rejected:'Từ chối'};
const menus={admin:['users'],staff:['inventory','orders','backorders'],planner:['inventory','demand','alerts','proposals','catalog','orders','backorders'],manager:['dashboard','proposals']};
const titles={users:'Quản trị tài khoản',password:'Đổi mật khẩu',dashboard:'Tổng quan',inventory:'Tồn kho',demand:'Phân tích nhu cầu',alerts:'Cảnh báo bổ sung',proposals:'Đề xuất nhập hàng',catalog:'Sản phẩm & nhà cung cấp',orders:'Đơn đã đặt',backorders:'Khách chờ hàng'};
const iconPaths={dashboard:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',inventory:'M3 7l9-4 9 4v10l-9 4-9-4z M3 7l9 4 9-4 M12 11v10',demand:'M4 19V5 M4 19h16 M8 15l4-5 4 2 4-7',alerts:'M12 3L2 20h20z M12 9v5 M12 17v1',proposals:'M6 3h9l4 4v14H6z M14 3v5h5 M9 12h7 M9 16h7',catalog:'M4 4h16v16H4z M4 9h16 M9 9v11',orders:'M3 6h18v14H3z M3 10h18 M8 3v5 M16 3v5',backorders:'M8 11a4 4 0 1 0 0-8 4 4 0 0 0 0 8z M2 21v-3a6 6 0 0 1 12 0v3 M17 8h5 M17 12h5 M18 16h4'};
const icon=k=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${iconPaths[k]||iconPaths.inventory}"/></svg>`;
function seed(){
  const products=[
    {id:'SKU-001',name:'Giấy A4 Double A 70gsm',unit:'ram',hand:60,lead:7,safety:40,target:300,complete:true,offers:[{supplier:'An Phát',price:60000},{supplier:'Minh Long',price:62000}]},
    {id:'SKU-008',name:'Bút bi Thiên Long',unit:'cây',hand:20,lead:4,safety:10,target:100,complete:true,offers:[{supplier:'Thiên Long',price:5000},{supplier:'An Phát',price:5200}]},
    {id:'SKU-002',name:'Bìa hồ sơ nhựa A4',unit:'cái',hand:480,lead:5,safety:20,target:600,complete:true,offers:[{supplier:'An Phát',price:8000}]},
    {id:'SKU-012',name:'Băng keo trong 48mm',unit:'cuộn',hand:80,lead:3,safety:10,target:150,complete:true,offers:[{supplier:'Minh Long',price:12000}]},
    {id:'SKU-015',name:'Sổ tay A5',unit:'quyển',hand:25,lead:5,safety:15,target:150,complete:false,offers:[{supplier:'Minh Long',price:25000}]}
  ];
  const sales=[];
  for(let d=0;d<30;d++){const date=new Date(Date.UTC(2026,9,3+d)).toISOString().slice(0,10);[10,5,8,3].forEach((qty,i)=>sales.push({date,sku:products[i].id,qty,kind:'Bán hàng',ref:`BH-${d+1}-${i+1}`}));}
  const lines=[{sku:'SKU-001',name:products[0].name,unit:'ram',supplier:'An Phát',price:60000,qty:210,suggested:210},{sku:'SKU-008',name:products[1].name,unit:'cây',supplier:'Thiên Long',price:5000,qty:80,suggested:80}];
  const proposals=[['DX-042','Draft'],['DX-041','Pending'],['DX-040','Approved'],['DX-039','Rejected']].map(([id,status])=>({id,status,budget:14000000,lines:structuredClone(lines),created:'01/11/2026',author:'Linh Nguyễn',created_by:'u-planner',reason:status==='Rejected'?'Cần đối chiếu lại báo giá giấy A4 với nhà cung cấp.':'',history:[{text:'Linh Nguyễn tạo đề xuất',time:'01/11/2026 · 09:00'},...(status!=='Draft'?[{text:'Linh Nguyễn gửi phê duyệt',time:'01/11/2026 · 10:00'}]:[]),...(status==='Approved'||status==='Rejected'?[{text:`Minh Anh ${status==='Approved'?'phê duyệt':'từ chối'}`,time:'01/11/2026 · 14:30'}]:[])]}));
  return {products,sales,proposals,suppliers:[{name:'An Phát',contact:'sales@anphat.example'},{name:'Thiên Long',contact:'sales@thienlong.example'},{name:'Minh Long',contact:'sales@minhlong.example'}],orders:[{id:'PO-026',sku:'SKU-001',party:'An Phát',qty:80,done:40,cancelled:0,history:[{text:'Linh Nguyễn ghi nhận đơn đã đặt: 80 ram',time:'31/10/2026 · 09:00'},{text:'Quốc Bảo nhận 40 ram',time:'01/11/2026 · 08:30'}]}],backorders:[{id:'BO-014',sku:'SKU-001',party:'Nhà sách Hoa Mai',qty:10,done:0,cancelled:0,history:[{text:'Linh Nguyễn ghi nhận khách chờ 10 ram',time:'01/11/2026 · 09:00'}]}],history:[{sku:'SKU-001',text:'Nhận 40 ram · PO-026 · Tồn thực tế 20 → 60',time:'01/11/2026 · 08:30',actor:'Quốc Bảo',reason:'Nhà cung cấp giao đợt 1'}]};
}
let db;try{db=JSON.parse(localStorage.getItem(KEY))||seed();}catch{db=seed();}
let role='planner', currentUser=null, accountSearch='', accountRole='', accountStatus='';
const actorName=()=>currentUser?.full_name||'';
function syncIdentity(){currentUser=A.current();if(currentUser)role=currentUser.role;return Boolean(currentUser);}
for(const q of db.proposals)q.created_by??='u-planner';
for(const record of [...db.proposals,...db.orders,...db.backorders])for(const h of record.history){h.actor_id??=h.text.startsWith('Quốc Bảo')?'u-staff':h.text.startsWith('Minh Anh')?'u-manager':'u-planner';}
for(const h of db.history)h.actor_id??='u-staff';
let statusFilter='all',search='',demandSku='SKU-001',dateFrom=START,dateTo=END,aiFailed=false;
const save=()=>localStorage.setItem(KEY,JSON.stringify(db));
const product=id=>db.products.find(p=>p.id===id);
const remaining=r=>r.qty-r.done-r.cancelled;
const onOrder=p=>db.orders.filter(r=>r.sku===p.id).reduce((s,r)=>s+remaining(r),0);
const back=p=>db.backorders.filter(r=>r.sku===p.id).reduce((s,r)=>s+remaining(r),0);
const position=p=>p.hand+onOrder(p)-back(p);
const demand=p=>p.complete?db.sales.filter(s=>s.sku===p.id&&s.date>=START&&s.date<=END).reduce((a,s)=>a+s.qty,0)/30:null;
const rop=p=>demand(p)==null?null:demand(p)*p.lead+p.safety;
const low=p=>rop(p)!=null&&position(p)<=rop(p);
const suggested=p=>p.complete?Math.max(0,p.target-position(p)):null;
const total=q=>q.lines.reduce((s,l)=>s+l.qty*l.price,0);
const stamp=()=>new Date().toLocaleString('vi-VN',{timeZone:'Asia/Ho_Chi_Minh'});
function history(q,text){q.history.push({text:`${actorName()} ${text}`,actor_id:currentUser.id,actor_name:actorName(),time:stamp()});}
const pill=(text,kind='neutral')=>`<span class="pill ${kind}">${esc(text)}</span>`;
const badge=q=>pill(labels[q.status],q.status);
const btn=(text,action,cls='primary',attrs='')=>`<button type="button" class="${cls}" data-action="${action}" ${attrs}>${text}</button>`;
const link=(text,route,cls='button')=>`<a class="${cls}" href="#${route}">${text}</a>`;
const notice=(title,body,kind='')=>`<div class="notice ${kind}"><strong>${title}</strong>${body}</div>`;
const metric=(label,value,sub,featured=false)=>`<div class="metric ${featured?'featured':''}"><div class="label">${label}</div><div class="number mono">${value}</div><small>${sub}</small></div>`;
const table=(heads,rows)=>`<div class="table-wrap"><table><thead><tr>${heads.map(x=>`<th scope="col">${x}</th>`).join('')}</tr></thead><tbody>${rows.length?rows.map(r=>`<tr>${r.map(c=>`<td>${c}</td>`).join('')}</tr>`).join(''):`<tr><td colspan="${heads.length}"><div class="empty">Không có dữ liệu phù hợp.</div></td></tr>`}</tbody></table></div>`;
const heading=(title,sub,actions='',kicker='WORKSPACE / STOCKMATE')=>`<div class="heading"><div><div class="kicker">${kicker}</div><h1>${title}</h1><p>${sub}</p></div><div class="actions">${actions}</div></div>`;
const timeline=q=>`<ul class="timeline">${q.history.map(h=>`<li>${esc(h.text)}<small>${esc(h.time)}</small></li>`).join('')}</ul>`;
const options=(list,current)=>list.map(([value,label])=>`<option value="${esc(value)}" ${value===current?'selected':''}>${esc(label)}</option>`).join('');
const pOptions=current=>options(db.products.map(p=>[p.id,`${p.id} · ${p.name}`]),current);
function toast(text){$('#toast').textContent=text;$('#toast').style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').style.display='none',4500);}
function go(route){if(location.hash==='#'+route)render();else location.hash=route;}
function route(){return (location.hash.slice(1)||menus[role][0]).split('/');}
function sectionFor(s){return ({product:'inventory',stock:'inventory',alert:'alerts',proposal:'proposals',editproduct:'catalog',record:'orders',user:'users'})[s]||s;}
function allowed(s){return s==='password'||menus[role].includes(sectionFor(s))||s==='user'&&role==='admin'||s==='record'&&['staff','planner'].includes(role);}
function shell(body,section){
  $('#app').innerHTML=`<div class="layout"><aside class="sidebar"><a class="brand" href="#${menus[role][0]}"><span class="logo">▣</span>StockMate</a><div class="eyebrow">Quản lý tồn kho</div><nav class="nav" aria-label="Điều hướng chính">${menus[role].map(k=>`<a href="#${k}" class="${section===k?'active':''}" ${section===k?'aria-current="page"':''}>${icon(k)}${titles[k]}</a>`).join('')}</nav><div class="sidebar-bottom"><div class="workspace-note"><strong>Một kho. Một nguồn dữ liệu.</strong><br>Theo dõi tồn kho và lên kế hoạch bổ sung trong cùng workspace.</div><div class="user"><span class="avatar">${esc(actorName().split(' ').map(p=>p[0]).slice(0,2).join(''))}</span><div><strong>${esc(actorName())}</strong><small>${roles[role]}</small></div></div></div></aside><div><header class="topbar"><div class="breadcrumb">Workspace <span aria-hidden="true">/</span> <strong>${titles[section]||'Chi tiết'}</strong></div><div class="demo"><span>PROTOTYPE · Dữ liệu mẫu 02/11/2026</span><span>${esc(currentUser.username)} · ${roles[role]}</span>${link('Đổi mật khẩu','password','button quiet small')}${btn('Đăng xuất','logout','quiet small')}${btn('Đặt lại mẫu','reset','quiet small')}</div></header><main class="content" id="main">${body}<div class="footer-note"><span>StockMate · Một kho / VND</span><span>Prototype cục bộ · AI mô phỏng · Chưa kết nối backend</span></div></main></div></div>`;
}
function dashboard(){
  const lows=db.products.filter(low),pending=db.proposals.filter(q=>q.status==='Pending'),missing=db.products.filter(p=>!p.complete);
  return heading('Tổng quan tồn kho','Những con số cần theo dõi. Những đề xuất cần quyết định.',btn('Xem đề xuất chờ duyệt →','pending-proposals'),'OVERVIEW / QUẢN LÝ')+`<div class="metrics">${metric('SKU đang hoạt động',num(db.products.length),'Trong danh mục sản phẩm',true)}${metric('Cần bổ sung',num(lows.length),'Inventory Position ≤ ROP')}${metric('Đề xuất chờ duyệt',num(pending.length),'Chờ quyết định của bạn')}${metric('SKU thiếu dữ liệu',num(missing.length),'Chưa thể kết luận mức tồn')}</div>`+notice('Ưu tiên hôm nay',`${pending.length} đề xuất đang chờ bạn xem xét. Phê duyệt ghi nhận quyết định; Planner ghi nhận đơn thực tế ở bước tiếp theo.`)+`<div class="card"><div class="toolbar"><div><h2>Đề xuất cần xử lý</h2><p class="sub">Kiểm tra sản phẩm, nhà cung cấp và ngân sách trước khi duyệt.</p></div>${pill('Cập nhật từ dữ liệu mẫu','good')}</div>${proposalTable(pending)}${link('Tất cả đề xuất →','proposals','button small')}</div><div class="two"><div class="card"><h2>Tình trạng bổ sung</h2>${table(['Sản phẩm','Position / ROP'],lows.map(p=>[esc(p.name),`${num(position(p))} / ${num(rop(p))} ${esc(p.unit)}`]))}</div><div class="card"><h2>Dữ liệu cần hoàn thiện</h2><p class="sub">Thiếu dữ liệu được tách riêng khỏi sản phẩm đủ hàng.</p>${missing.map(p=>notice(esc(p.name),'Lịch sử bán hàng chưa đầy đủ · Nhu cầu và ROP: —','warn')).join('')}</div></div>`;
}
function inventory(){
 const list=db.products.filter(p=>(p.id+' '+p.name).toLowerCase().includes(search.toLowerCase()));
 return heading('Tồn kho','Tra cứu số lượng hiện có, đang về và khách còn chờ hàng.',pill('01 kho · '+db.products.length+' SKU','neutral'))+`<div class="metrics">${metric('SKU theo dõi',db.products.length,'Danh mục đang hoạt động',true)}${metric('Đơn đang về',db.orders.filter(r=>remaining(r)>0).length,'Có số lượng chưa nhận')}${metric('Khách chờ hàng',db.backorders.filter(r=>remaining(r)>0).length,'Có số lượng chưa giao')}${metric('Cần bổ sung',db.products.filter(low).length,'Theo Inventory Position')}</div><div class="card"><div class="toolbar"><input id="search" class="search" aria-label="Tìm SKU hoặc sản phẩm" placeholder="Tìm theo SKU hoặc tên sản phẩm…" value="${esc(search)}"><span class="label">${list.length} / ${db.products.length} sản phẩm</span></div>${!list.length?`<div class="empty"><h2>Không tìm thấy sản phẩm</h2><p>Không có sản phẩm khớp “${esc(search)}”. Thử từ khóa khác.</p>${btn('Xóa tìm kiếm','clear-search','quiet')}</div>`:table(['SKU / Sản phẩm','Đơn vị','Hiện có','Đang đặt','Khách chờ','Position',...(role==='planner'?['ROP']:[]),'Tình trạng',''],list.map(p=>[`<strong>${esc(p.name)}</strong><small>${p.id}</small>`,esc(p.unit),num(p.hand),num(onOrder(p)),num(back(p)),`<strong>${num(position(p))}</strong>`,...(role==='planner'?[num(rop(p))]:[]),!p.complete?pill('Thiếu dữ liệu','warn'):low(p)?pill('Cần bổ sung','bad'):pill('Đủ hàng','good'),link('Chi tiết →','product/'+p.id,'')]))}<div class="table-foot">Inventory Position = Hiện có + Đang đặt − Khách chờ hàng</div></div>`;
}
function productDetail(id){const p=product(id);if(!p)return notFound();
 return heading(esc(p.name),`${p.id} · Đơn vị: ${esc(p.unit)}`,link('← Tồn kho','inventory'))+`<div class="metrics">${metric('Hiện có',num(p.hand),esc(p.unit),true)}${metric('Đang đặt',num(onOrder(p)),esc(p.unit)+' chưa nhận')}${metric('Khách chờ',num(back(p)),esc(p.unit)+' chưa giao')}${metric('Inventory Position',num(position(p)),`${num(p.hand)} + ${num(onOrder(p))} − ${num(back(p))}`)}</div><div class="split"><div><div class="card"><h2>${role==='staff'?'Ghi nhận biến động':'Thông tin kế hoạch'}</h2><p class="sub">${role==='staff'?'Chọn đúng loại nghiệp vụ để giữ tồn kho và lịch sử bán chính xác.':'Dữ liệu dùng cho phân tích nhu cầu và đề xuất bổ sung.'}</p>${role==='staff'?`<div class="actions">${link('Nhận hàng','stock/'+id+'/receipt','button primary')}${link('Xuất bán / Giao khách','stock/'+id+'/sale')}${link('Kiểm kê thực tế','stock/'+id+'/count')}</div>`:`<div class="summary-line"><span>Lead time</span><strong>${p.lead} ngày</strong></div><div class="summary-line"><span>Tồn an toàn / Mục tiêu</span><strong>${p.safety} / ${p.target} ${esc(p.unit)}</strong></div><div class="actions">${link('Phân tích nhu cầu →','demand')}${link('Xem cơ sở bổ sung →','alert/'+id)}</div>`}</div><div class="card"><h2>Lịch sử thay đổi tồn kho</h2>${db.history.filter(h=>h.sku===id).length?`<ul class="timeline">${db.history.filter(h=>h.sku===id).slice().reverse().map(h=>`<li>${esc(h.text)}<small>${esc(h.actor)} · ${esc(h.time)}<br>Lý do: ${esc(h.reason)}</small></li>`).join('')}</ul>`:'<p class="sub">Chưa có biến động trong dữ liệu mẫu.</p>'}</div></div><div class="card"><h2>Hồ sơ sản phẩm</h2><div class="summary-line"><span>SKU</span><strong>${id}</strong></div><div class="summary-line"><span>Đơn vị</span><strong>${esc(p.unit)}</strong></div><h3>Nhà cung cấp</h3>${p.offers.map(o=>`<div class="summary-line"><span>${esc(o.supplier)}</span><strong>${money(o.price)}</strong></div>`).join('')}${link('Đơn đang đặt →','orders','button small')}${link('Khách chờ hàng →','backorders','button small')}</div></div>`;
}
function stockForm(id,type){const p=product(id);if(!p)return notFound();if(role!=='staff')return denied();const count=type==='count',receipt=type==='receipt';
 const records=receipt?db.orders.filter(r=>r.sku===id&&remaining(r)>0):db.backorders.filter(r=>r.sku===id&&remaining(r)>0);
 return heading(count?'Kiểm kê thực tế':receipt?'Nhận hàng từ nhà cung cấp':'Xuất bán / Giao khách chờ',`${id} · ${esc(p.name)}`,link('← Chi tiết sản phẩm','product/'+id))+`<div class="split"><form class="card stock-form" id="stock-form" data-sku="${id}" data-type="${type}"><h2>${count?'Nhập tổng số đếm được':'Ghi nhận số lượng thực tế'}</h2><p class="sub">Hiện có: ${p.hand} ${esc(p.unit)} · Đang đặt: ${onOrder(p)} · Khách chờ: ${back(p)}</p><div class="fields">${!count?`<label class="wide">${receipt?'Đơn đã đặt *':'Liên kết khách chờ hàng (nếu có)'}<select name="record" ${receipt?'required':''}>${!receipt?'<option value="">Bán trực tiếp · Không liên kết backorder</option>':'<option value="">Chọn đơn đã đặt</option>'}${options(records.map(r=>[r.id,`${r.id} · ${r.party} · Còn ${remaining(r)} ${p.unit}`]),'')}</select></label>`:''}<label class="wide">${count?'Tổng tồn thực tế sau kiểm kê':'Số lượng '+(receipt?'nhận':'giao')} (${esc(p.unit)}) *<input name="qty" type="number" min="${count?0:1}" step="1" required placeholder="${count?'Ví dụ: 75':'Nhập số lượng thực tế'}"><small>${count?'Nhập tổng số đếm được, không nhập phần chênh lệch.':'Cho phép từng phần. Không vượt số lượng còn lại'+(!receipt?' hoặc tồn hiện có.':'.')}</small></label><label class="wide">Lý do / Ghi chú *<textarea name="reason" required placeholder="Ghi rõ lý do để đối chiếu lịch sử"></textarea></label></div><div class="error" id="form-error" role="alert"></div><div class="form-footer">${link('Hủy','product/'+id)}<button class="primary" type="submit">Lưu ${count?'kiểm kê':receipt?'phiếu nhận':'phiếu xuất'}</button></div></form><div>${notice(count?'Kiểm kê không phải bán hàng':receipt?'Nhận đúng đơn đã đặt':'Chỉ ghi nhận doanh số một lần',count?'Tồn hiện có được thay bằng số đếm thực tế. Không cộng vào lịch sử bán.':receipt?'Tồn hiện có tăng, số đang đặt giảm cùng số lượng nhận. Phần chưa nhận vẫn được giữ lại.':'Nếu giao cho khách chờ, tồn hiện có và backorder cùng giảm; chỉ tạo một dòng bán hàng.')}<div class="card"><h3>Người ghi nhận</h3><strong>${esc(actorName())}</strong><p class="sub">Lưu thời điểm và lý do cùng biến động.</p></div></div></div>`;
}
function demandView(){const p=product(demandSku)||db.products[0],avg=demand(p),sales=db.sales.filter(s=>s.sku===p.id&&s.date>=dateFrom&&s.date<=dateTo);const days=Array.from({length:30},(_,i)=>new Date(Date.UTC(2026,9,3+i)).toISOString().slice(0,10));const vals=days.map(d=>db.sales.filter(s=>s.sku===p.id&&s.date===d).reduce((s,r)=>s+r.qty,0));
 return heading('Phân tích nhu cầu','Hiểu sức bán trước khi quyết định số lượng bổ sung.',link('Cảnh báo bổ sung →','alerts','button primary'))+`<div class="card"><div class="inline-form"><label>Sản phẩm<select id="demand-sku">${pOptions(p.id)}</select></label><label>Lịch sử từ ngày<input id="date-from" type="date" value="${dateFrom}" max="${TODAY}"></label><label>Đến ngày<input id="date-to" type="date" value="${dateTo}" max="${TODAY}"></label>${btn('Lọc lịch sử','filter-sales','primary')}</div><p class="help">Bộ lọc chỉ thay đổi lịch sử bên dưới. Nhu cầu luôn dùng 30 ngày hoàn tất: 03/10–01/11/2026, không gồm hôm nay.</p><div id="date-error" role="alert" class="error"></div></div>${avg==null?notice('Thiếu lịch sử bán hàng đầy đủ',`${p.id}: chưa xác nhận đủ dữ liệu 30 ngày. Nhu cầu, ROP và số lượng khuyến nghị hiển thị —; không thay bằng 0.`,'warn'):''}<div class="metrics">${metric('Tổng bán · 30 ngày',avg==null?'—':num(avg*30),esc(p.unit),true)}${metric('Nhu cầu TB / ngày',num(avg),`${avg==null?'Chưa thể tính':num(avg*30)+' ÷ 30'} ${esc(p.unit)}`)}${metric('Lead time',p.lead,'ngày')}${metric('Điểm đặt hàng ROP',num(rop(p)),`${avg==null?'Thiếu dữ liệu':num(avg)+' × '+p.lead+' + '+p.safety}`)}</div><div class="card"><div class="toolbar"><div><h2>Nhịp bán trong 30 ngày</h2><p class="sub">${esc(p.name)} · Đơn vị: ${esc(p.unit)} / ngày</p></div>${pill(avg==null?'Thiếu dữ liệu':'Đủ dữ liệu',avg==null?'warn':'good')}</div>${avg==null?'<div class="empty">Chưa thể dựng biểu đồ từ dữ liệu thiếu.</div>':`<div class="chart" aria-label="Số lượng bán theo ngày">${vals.map((v,i)=>`<div class="bar" style="height:${v/Math.max(...vals,1)*130}px" title="${days[i]}: ${v} ${esc(p.unit)}"></div>`).join('')}</div><div class="chart-labels"><span>03/10/2026</span><span>17/10/2026</span><span>01/11/2026</span></div>`}</div><div class="card"><h2>Lịch sử bán hàng</h2><p class="sub">Bao gồm giao backorder một lần; loại trừ nhận hàng và kiểm kê. Bộ lọc: ${dateFrom} → ${dateTo}.</p>${table(['Ngày','Chứng từ','Nghiệp vụ',`Số lượng (${esc(p.unit)})`],sales.slice().reverse().map(s=>[esc(s.date),esc(s.ref),esc(s.kind),num(s.qty)]))}</div>`;
}
function alerts(){return heading('Cảnh báo bổ sung','Kiểm tra Inventory Position và cơ sở tính trước khi lập đề xuất.',btn('↻ Kiểm tra lại','refresh-alerts'))+notice('Dữ liệu kiểm tra · 02/11/2026','Nhu cầu lấy từ 03/10–01/11/2026. Prototype hỗ trợ kiểm tra theo yêu cầu; lịch kiểm tra hằng ngày thuộc backend.')+`<div class="card"><div class="toolbar"><h2>Sản phẩm cần bổ sung</h2>${pill(db.products.filter(low).length+' SKU','warn')}</div>${table(['SKU / Sản phẩm','Hiện có','Đang đặt','Khách chờ','Position','ROP','Gợi ý nhập',''],db.products.filter(low).map(p=>[`<strong>${esc(p.name)}</strong><small>${p.id} · ${esc(p.unit)}</small>`,num(p.hand),num(onOrder(p)),num(back(p)),`<strong>${num(position(p))}</strong>`,num(rop(p)),num(suggested(p)),link('Xem cơ sở →','alert/'+p.id,'')]))}</div><div class="card"><h2>Chưa thể kết luận</h2><p class="sub">Sản phẩm thiếu dữ liệu không được xếp vào nhóm đủ hàng.</p>${table(['Sản phẩm','Nguyên nhân','Nhu cầu / ROP / Gợi ý'],db.products.filter(p=>!p.complete).map(p=>[esc(p.name),'Thiếu lịch sử bán 30 ngày','— / — / —']))}</div>`;}
function alertDetail(id){const p=product(id);if(!p)return notFound();return heading('Cơ sở đề xuất bổ sung',`${id} · ${esc(p.name)}`,link('← Cảnh báo','alerts'))+`<div class="split"><div><div class="card"><h2>Từ tồn kho đến số lượng đề xuất</h2><p class="sub">Mỗi thành phần đều có thể đối chiếu.</p>${table(['Thành phần',`Giá trị (${esc(p.unit)})`],[['Tồn hiện có',num(p.hand)],['Đang đặt · Chưa nhận',num(onOrder(p))],['Khách chờ · Chưa giao',num(back(p))],['Inventory Position',`<strong>${num(position(p))}</strong>`],['Nhu cầu trung bình / ngày',num(demand(p))],['Lead time',p.lead+' ngày'],['Tồn an toàn',p.safety],['ROP',num(rop(p))],['Mục tiêu tồn',p.target]])}<div class="equation">Position = ${p.hand} + ${onOrder(p)} − ${back(p)} = ${position(p)}<br>ROP = ${num(demand(p))} × ${p.lead} + ${p.safety} = ${num(rop(p))}<br>Gợi ý = max(0, ${p.target} − ${position(p)}) = ${num(suggested(p))}</div></div></div><div class="card"><h2>${!p.complete?'Chưa đủ dữ liệu':low(p)?'Cần bổ sung':'Chưa chạm ROP'}</h2><p class="sub">${!p.complete?'Chưa thể đưa ra khuyến nghị số lượng.':`Position ${position(p)} ${low(p)?'≤':'>'} ROP ${num(rop(p))}`}</p><div class="summary-total">${num(suggested(p))} <small>${esc(p.unit)}</small></div><p class="sub">Số lượng khuyến nghị</p>${btn('Tạo bản nháp','new-proposal','primary',`data-sku="${id}" ${!p.complete?'disabled':''}`)}<p class="help">Planner chọn nhà cung cấp, kiểm tra ngân sách và gửi duyệt.</p></div></div>`;}
function proposalTable(list){return table(['Đề xuất','Sản phẩm / NCC','Tổng tiền','Ngân sách','Người tạo','Trạng thái',''],list.map(q=>[`<strong>${q.id}</strong><small>${esc(q.created)}</small>`,`${q.lines.length} sản phẩm · ${new Set(q.lines.map(l=>l.supplier)).size} NCC`,money(total(q)),money(q.budget),esc(q.author),badge(q),link('Chi tiết →','proposal/'+q.id,'')]));}
function proposalList(){const list=db.proposals.filter(q=>(q.status!=='Draft'||role==='planner'&&q.created_by===currentUser.id)&&(statusFilter==='all'||q.status===statusFilter));return heading('Đề xuất nhập hàng','Từ bản nháp đến quyết định, với chi phí và lịch sử rõ ràng.',role==='planner'?btn('+ Tạo đề xuất','new-proposal'):'')+`<div class="card"><div class="toolbar"><div class="tabs">${['all',...(role==='planner'?['Draft']:[]),'Pending','Approved','Rejected'].map(s=>btn(s==='all'?'Tất cả':labels[s],'status-filter',statusFilter===s?'active':'quiet',`data-value="${s}"`)).join('')}</div><span class="label">${list.length} đề xuất</span></div>${proposalTable(list)}</div>`;}
function proposalDetail(id){const q=db.proposals.find(q=>q.id===id);if(!q)return notFound();if(q.status==='Draft'&&(role!=='planner'||q.created_by!==currentUser.id))return denied();const edit=requireDraft(q),sum=total(q),over=sum>q.budget;
return heading(`Đề xuất ${q.id}`,`${esc(q.author)} · Tạo ngày ${esc(q.created)}${q.source?' · Sao chép từ '+esc(q.source):''}`,`${badge(q)}${link('← Danh sách','proposals')}`)+`<div class="flow"><span class="${q.status==='Draft'?'current':''}">01 / Chuẩn bị</span>→<span class="${q.status==='Pending'?'current':''}">02 / Chờ duyệt</span>→<span class="${['Approved','Rejected'].includes(q.status)?'current':''}">03 / Quyết định</span></div>${q.source?notice('Bản nháp được sao chép',`Bản gốc ${link(esc(q.source),'proposal/'+q.source,'')} giữ nguyên. Giá và gợi ý đã lấy lại từ dữ liệu hiện tại; hãy kiểm tra trước khi gửi.`):''}${q.status==='Approved'?notice('Đã phê duyệt',`Quyết định đã được ghi nhận. Chưa tạo đơn và chưa thay đổi tồn kho. ${role==='planner'?link('Ghi nhận đơn đã đặt →','record/orders/new',''):''}`):''}${q.status==='Rejected'?notice('Đề xuất đã bị từ chối',`Lý do: ${esc(q.reason)}. Bản gốc được giữ nguyên.`,'bad'):''}${q.status==='Pending'?notice('Đang chờ Quản lý xem xét','Đề xuất đã gửi được giữ ở chế độ chỉ đọc. AI và Planner không chỉnh sửa trạng thái này.') :''}<div class="split"><div><div class="card"><div class="toolbar"><div><h2>Sản phẩm trong đề xuất</h2><p class="sub">${q.lines.length} sản phẩm · ${new Set(q.lines.map(l=>l.supplier)).size} nhà cung cấp · Đơn giá VND</p></div>${edit?btn('+ Thêm sản phẩm','add-line','quiet small',`data-id="${id}"`):''}</div>${table(['Sản phẩm', 'Nhà cung cấp','Gợi ý','SL chọn','Đơn giá','Thành tiền',...(edit?['']:[])],q.lines.map((l,i)=>{const p=product(l.sku);return [`<strong>${esc(l.name)}</strong><small>${l.sku} · ${esc(l.unit)}</small>`,edit?`<select aria-label="Nhà cung cấp ${l.sku}" data-edit="supplier" data-id="${id}" data-index="${i}">${options(p.offers.map(o=>[o.supplier,o.supplier]),l.supplier)}</select>`:esc(l.supplier),num(l.suggested),edit?`<input type="number" min="1" step="1" aria-label="Số lượng ${l.sku}" value="${l.qty}" data-edit="qty" data-id="${id}" data-index="${i}">`:num(l.qty),money(l.price),`<strong>${money(l.price*l.qty)}</strong>`,...(edit?[btn('×','remove-line','quiet small',`data-id="${id}" data-index="${i}" aria-label="Xóa ${l.sku}"`)]:[])];}))}<p class="help">Gợi ý = max(0, Mục tiêu − Inventory Position). Planner có thể chọn số lượng khác.</p><div id="proposal-error" class="error" role="alert"></div>${edit?`<div class="ai"><h3>✦ Trợ lý bản nháp</h3><p>Gợi ý từ dữ liệu mẫu và phép tính cục bộ. Bạn chọn nhà cung cấp và quyết định áp dụng. AI chỉ hỗ trợ bản nháp.</p><label>Yêu cầu mẫu<select id="ai-request"><option value="explain">Giải thích cơ sở và số lượng đề xuất</option><option value="suggest">Đề nghị cập nhật SL theo gợi ý mới nhất</option></select></label><div class="actions">${btn('Xem gợi ý','ai','quiet',`data-id="${id}"`)}${btn(aiFailed?'Bật lại AI mẫu':'Mô phỏng AI lỗi','ai-fail','quiet small')}</div><div id="ai-result" aria-live="polite">${aiFailed?notice('Trợ lý tạm thời không khả dụng','Bản nháp vẫn được giữ. Tiếp tục bằng các trường sản phẩm, nhà cung cấp, số lượng và ngân sách bên trên.','warn'):''}</div></div>`:''}</div><div class="card"><h2>Lịch sử chỉnh sửa & quyết định</h2>${timeline(q)}</div></div><aside><div class="card"><h2>Ngân sách đề xuất</h2>${edit?`<label>Hạn mức riêng (VND)<input id="budget" type="number" min="0" step="1000" value="${q.budget}" data-edit="budget" data-id="${id}"></label>`:`<div class="summary-line"><span>Hạn mức</span><strong>${money(q.budget)}</strong></div>`}<div class="summary-total">${money(sum)}</div><div class="label">Tổng chi phí dự kiến</div><div class="progress ${over?'over':''}"><span style="width:${q.budget?Math.min(100,sum/q.budget*100):100}%"></span></div><div class="summary-line"><span>${over?'Vượt ngân sách':'Còn trong hạn mức'}</span><strong style="color:${over?'var(--red)':'var(--green)'}">${money(Math.abs(q.budget-sum))}</strong></div>${over?notice('Chưa thể gửi duyệt','Hãy sửa số lượng, xóa sản phẩm hoặc tăng ngân sách. Hệ thống không tự giảm số lượng.','bad'):''}${edit?`<div class="stack">${btn('Lưu bản nháp','save-draft','quiet',`data-id="${id}"`)}${btn('Gửi phê duyệt →','submit-proposal','primary',`data-id="${id}" ${over||!q.lines.length?'disabled':''}`)}</div>`:role==='manager'&&q.status==='Pending'?`<div class="stack">${btn('Phê duyệt đề xuất','approve','primary',`data-id="${id}"`)}${btn('Từ chối…','reject','danger',`data-id="${id}"`)}</div>`:role==='planner'&&q.status==='Rejected'?btn('Sao chép thành bản nháp','copy','primary',`data-id="${id}"`):''}<p class="help">Ngân sách riêng từng đề xuất. Phê duyệt không trừ vào quỹ chung.</p></div>${!edit?`<div class="hero-note">Đơn giá, tên sản phẩm và đơn vị trong đề xuất được lưu tại thời điểm lập. Thay đổi danh mục không sửa lịch sử đề xuất.</div>`:''}</aside></div>`;
}
function catalog(){return heading('Sản phẩm & nhà cung cấp','Quản lý dữ liệu nền để các đề xuất có cơ sở chính xác.',link('+ Thêm sản phẩm','editproduct/new','button primary'))+`<div class="card"><h2>Danh mục & chính sách tồn kho</h2><p class="sub">Lead time theo ngày · Giá theo nhà cung cấp · Mục tiêu theo đơn vị sản phẩm</p>${table(['Sản phẩm','Đơn vị','Lead time','An toàn','Mục tiêu','Nhà cung cấp / Giá',''],db.products.map(p=>[`<strong>${esc(p.name)}</strong><small>${p.id}</small>`,esc(p.unit),p.lead+' ngày',num(p.safety),num(p.target),p.offers.map(o=>`${esc(o.supplier)} · ${money(o.price)}`).join('<br>'),link('Chỉnh sửa','editproduct/'+p.id,'')]))}</div><div class="card"><div class="toolbar"><div><h2>Nhà cung cấp</h2><p class="sub">Thông tin liên hệ dùng trong quy trình lập kế hoạch.</p></div>${btn('+ Thêm nhà cung cấp','supplier-form','quiet')}</div>${table(['Tên nhà cung cấp','Liên hệ',''],db.suppliers.map((s,i)=>[esc(s.name),esc(s.contact),btn('Chỉnh sửa','supplier-form','quiet small',`data-index="${i}"`)]))}</div>`;}
function editProduct(id){const p=product(id)||{id:'',name:'',unit:'cái',lead:1,safety:0,target:100,offers:[]};return heading(id==='new'?'Thêm sản phẩm':'Chỉnh sửa sản phẩm','Giá mới chỉ áp dụng cho các đề xuất được lập hoặc sao chép tiếp theo.',link('← Danh mục','catalog'))+`<form id="product-form" class="card" data-id="${esc(id)}"><div class="fields"><label>SKU *<input name="sku" value="${esc(p.id)}" ${p.id?'readonly':''} required pattern="[A-Za-z0-9_-]+"></label><label>Tên sản phẩm *<input name="name" value="${esc(p.name)}" required></label><label>Đơn vị *<input name="unit" value="${esc(p.unit)}" required></label><label>Lead time (ngày) *<input name="lead" type="number" min="0" step="1" value="${p.lead}" required></label><label>Tồn an toàn *<input name="safety" type="number" min="0" step="1" value="${p.safety}" required></label><label>Mục tiêu tồn *<input name="target" type="number" min="0" step="1" value="${p.target}" required></label></div><h3 style="margin-top:25px">Liên kết nhà cung cấp & đơn giá</h3><p class="sub">Đánh dấu các nhà cung cấp cung ứng sản phẩm này. Mỗi nhà cung cấp có một đơn giá.</p>${db.suppliers.map((s,i)=>{const o=p.offers.find(o=>o.supplier===s.name);return `<div class="inline-form" style="margin:12px 0"><label><input type="checkbox" name="offer-${i}" ${o?'checked':''} style="display:inline;width:16px;min-height:0"> ${esc(s.name)}</label><label>Giá (VND)<input name="price-${i}" type="number" min="0" step="100" value="${o?.price||0}"></label></div>`;}).join('')}<div id="form-error" class="error" role="alert"></div><div class="form-footer">${link('Hủy','catalog')}<button type="submit" class="primary">Lưu sản phẩm</button></div></form>`;}
function recordsView(kind){const order=kind==='orders',list=db[kind];return heading(order?'Đơn đã đặt':'Khách chờ hàng',order?'Ghi nhận các đơn đã thực sự đặt với nhà cung cấp.':'Theo dõi phần hàng còn nợ khách do thiếu hàng.',role==='planner'?link(order?'+ Ghi nhận đơn đã đặt':'+ Ghi nhận khách chờ','record/'+kind+'/new','button primary'):'')+notice(order?'Tách biệt với phê duyệt đề xuất':'Theo dõi đúng phần chưa giao',order?'Chỉ ghi nhận đơn đã đặt mới tăng số đang đặt. Nhận hàng từng phần giảm phần còn lại.':'Giao hàng giảm tồn hiện có và số khách chờ; ghi nhận bán một lần. Hủy phần còn lại không làm thay đổi tồn hiện có.')+`<div class="card"><h2>${order?'Danh sách đơn mua':'Danh sách backorder'}</h2><p class="sub">Số còn lại = Ban đầu − ${order?'Đã nhận':'Đã giao'} − Đã hủy</p>${table(['Chứng từ / Đối tác','Sản phẩm','Ban đầu',order?'Đã nhận':'Đã giao','Đã hủy','Còn lại','Thao tác'],list.map(r=>{const p=product(r.sku);return [`<strong>${r.id}</strong><small>${esc(r.party)}</small>`,`${esc(p.name)}<small>${p.id} · ${esc(p.unit)}</small>`,r.qty,r.done,r.cancelled,`<strong>${remaining(r)}</strong>`,`${link('Chi tiết','record/'+kind+'/'+r.id,'')} ${remaining(r)>0?(role==='staff'?link(order?'Nhận hàng →':'Giao khách →','stock/'+p.id+'/'+(order?'receipt':'sale'),'button small'):btn('Hủy phần còn lại','cancel-record','quiet small',`data-kind="${kind}" data-id="${r.id}"`)):pill('Hoàn tất','good')}`];}))}</div>`;}
function recordDetail(kind,id){if(!['orders','backorders'].includes(kind))return notFound();const order=kind==='orders';if(id==='new'){if(role!=='planner')return denied();return heading(order?'Ghi nhận đơn đã đặt':'Ghi nhận khách chờ hàng',order?'Nhập số lượng đã xác nhận đặt với nhà cung cấp.':'Nhập số lượng khách chưa được đáp ứng do thiếu hàng.',link('← Danh sách',kind))+`<form id="record-form" class="card stock-form" data-kind="${kind}"><div class="fields"><label class="wide">Sản phẩm *<select name="sku" id="record-sku">${pOptions(db.products[0].id)}</select></label><label class="wide">${order?'Nhà cung cấp':'Tên khách hàng'} *${order?`<select name="party" id="record-party">${options(db.products[0].offers.map(o=>[o.supplier,o.supplier]),'')}</select>`:'<input name="party" required placeholder="Tên khách hàng đang chờ">'}</label><label>Số lượng ban đầu *<input name="qty" type="number" min="1" step="1" required></label><label>Ngày ghi nhận<input type="date" name="date" value="${TODAY}" required max="${TODAY}"></label><label class="wide">Ghi chú *<textarea name="reason" required placeholder="Tham chiếu đơn thực tế / nhu cầu khách"></textarea></label></div><div id="form-error" class="error" role="alert"></div><div class="form-footer">${link('Hủy',kind)}<button class="primary" type="submit">Lưu ghi nhận</button></div></form>`;}
 const r=db[kind].find(r=>r.id===id);if(!r)return notFound();const p=product(r.sku);return heading(`${id} · ${esc(r.party)}`,`${p.id} · ${esc(p.name)} · ${esc(p.unit)}`,link('← Danh sách',kind))+`<div class="metrics">${metric('Ban đầu',r.qty,esc(p.unit),true)}${metric(order?'Đã nhận':'Đã giao',r.done,esc(p.unit))}${metric('Đã hủy',r.cancelled,esc(p.unit))}${metric('Còn lại',remaining(r),esc(p.unit))}</div><div class="card"><h2>Lịch sử chứng từ</h2>${timeline(r)}${remaining(r)>0?(role==='staff'?link(order?'Nhận hàng từng phần':'Giao hàng từng phần','stock/'+p.id+'/'+(order?'receipt':'sale'),'button primary'):btn('Hủy phần còn lại…','cancel-record','danger',`data-kind="${kind}" data-id="${id}"`)):pill('Không còn số lượng outstanding','good')}</div>`;
}
function denied(){return heading('Không có quyền truy cập','Vai trò hiện tại không thực hiện nghiệp vụ này.')+link('Về trang của tôi',menus[role][0],'button primary');}
function notFound(){return heading('Không tìm thấy nội dung','Kiểm tra lại liên kết hoặc quay về trang chính.')+link('Về trang chính',menus[role][0],'button primary');}
let isRendering=false;
function render(){if(isRendering)return;isRendering=true;try{renderView();}finally{isRendering=false;}}
function renderView(){if(!syncIdentity()){$('#app').innerHTML=AV.login();return;}if(currentUser.must_change_password){shell(AV.password(currentUser),'password');return;}const [s,id,type]=route();const section=s==='record'?id:sectionFor(s);let body;if(!allowed(s))body=denied();else switch(s){case'users':body=AV.users(accountSearch,accountRole,accountStatus);break;case'user':body=AV.user(id);break;case'password':body=AV.password(currentUser);break;case'dashboard':body=dashboard();break;case'inventory':body=inventory();break;case'product':body=productDetail(id);break;case'stock':body=['receipt','sale','count'].includes(type)?stockForm(id,type):notFound();break;case'demand':body=demandView();break;case'alerts':body=alerts();break;case'alert':body=alertDetail(id);break;case'proposals':body=proposalList();break;case'proposal':body=proposalDetail(id);break;case'catalog':body=catalog();break;case'editproduct':body=editProduct(id);break;case'orders':case'backorders':body=recordsView(s);break;case'record':body=recordDetail(id,type);break;default:body=notFound();}shell(body,section);}
function modal(title,body,footer=''){const d=$('#dialog');d.innerHTML=`<h2 id="dialog-title">${title}</h2>${body}${footer}`;d.showModal();}
function close(){ $('#dialog').close(); $('#dialog').innerHTML=''; }
function qById(id){return db.proposals.find(q=>q.id===id);}
function requireDraft(q){return role==='planner'&&q?.status==='Draft'&&q.created_by===currentUser?.id;}
function currentLine(p){const o=p.offers[0];return {sku:p.id,name:p.name,unit:p.unit,supplier:o.supplier,price:o.price,qty:suggested(p)||1,suggested:suggested(p)};}
function makeDraft(lines,source){let i=43;while(qById('DX-'+i))i++;const q={id:'DX-'+i,status:'Draft',budget:14000000,lines,created:'02/11/2026',author:actorName(),created_by:currentUser.id,history:[],...(source?{source}:{})};history(q,source?'sao chép từ '+source:'tạo bản nháp');db.proposals.unshift(q);save();go('proposal/'+q.id);}
function handleAction(b){const a=b.dataset.action,id=b.dataset.id,q=qById(id);
 if(!syncIdentity()){render();return;}
 if(a==='logout'){A.logout();close();go('login');return;}
 if(currentUser.must_change_password){render();return;}
 switch(a){
 case'reset-user-password':if(role==='admin')modal('Cấp lại mật khẩu tạm',`<form id="reset-password-form" data-id="${esc(id)}"><p>Tài khoản phải đăng nhập lại và đổi mật khẩu ở lần tiếp theo.</p><label>Mật khẩu tạm<input name="password" type="password" minlength="8" maxlength="128" required autocomplete="new-password"></label><div id="account-error" class="error" role="alert"></div><div class="form-footer">${btn('Hủy','close','quiet')}<button type="submit" class="primary">Cấp mật khẩu tạm</button></div></form>`);break;
 case'reset':modal('Đặt lại dữ liệu mẫu?','<p>Dữ liệu nghiệp vụ sẽ được thay bằng bộ mẫu ban đầu. Tài khoản và mật khẩu được giữ nguyên.</p>',`<div class="form-footer">${btn('Giữ dữ liệu','close','quiet')}${btn('Đặt lại','confirm-reset','danger')}</div>`);break;
 case'confirm-reset':db=seed();save();search='';statusFilter='all';aiFailed=false;close();render();toast('Đã khôi phục dữ liệu mẫu.');break;
 case'close':close();break;
 case'clear-search':search='';render();break;
 case'status-filter':statusFilter=b.dataset.value;render();break;
 case'pending-proposals':if(role==='manager'){statusFilter='Pending';go('proposals');}break;
 case'filter-sales':{const from=$('#date-from').value,to=$('#date-to').value;if(!from||!to||from>to){$('#date-error').textContent='Ngày bắt đầu phải không sau ngày kết thúc.';return;}dateFrom=from;dateTo=to;render();break;}
 case'refresh-alerts':render();toast('Đã kiểm tra lại cảnh báo từ dữ liệu hiện tại.');break;
 case'new-proposal':if(role==='planner'){const p=product(b.dataset.sku);makeDraft(p&&p.complete?[currentLine(p)]:[]);}break;
 case'add-line':if(requireDraft(q)){const list=db.products.filter(p=>!q.lines.some(l=>l.sku===p.id));modal('Thêm sản phẩm',`<form id="add-line-form" data-id="${id}"><label>Sản phẩm<select name="sku" required>${options(list.map(p=>[p.id,`${p.name}${!p.complete?' · Thiếu dữ liệu, nhập SL thủ công':''}`]),'')}</select></label><p class="help">Với dữ liệu thiếu, số lượng mặc định 1 chỉ là giá trị nhập thủ công, không phải khuyến nghị.</p><div class="form-footer">${btn('Hủy','close','quiet')}<button type="submit" class="primary" ${!list.length?'disabled':''}>Thêm vào bản nháp</button></div></form>`);}break;
 case'remove-line':if(requireDraft(q)){q.lines.splice(Number(b.dataset.index),1);history(q,'xóa một dòng sản phẩm');save();render();}break;
 case'save-draft':if(requireDraft(q)){history(q,'lưu bản nháp');save();render();toast('Đã lưu bản nháp trên trình duyệt.');}break;
 case'submit-proposal':if(requireDraft(q)){const invalid=[...document.querySelectorAll('[data-edit]')].find(el=>!el.checkValidity());if(invalid){invalid.reportValidity();return;}if(!q.lines.length||total(q)>q.budget||q.lines.some(l=>!Number.isInteger(l.qty)||l.qty<1)){toast('Kiểm tra sản phẩm, số lượng và ngân sách trước khi gửi.');return;}q.status='Pending';history(q,'gửi phê duyệt');save();render();toast('Đã gửi. Trạng thái: Chờ duyệt.');}break;
 case'approve':if(role==='manager'&&q?.status==='Pending'){q.status='Approved';history(q,'phê duyệt đề xuất');save();render();toast('Đã phê duyệt. Tồn kho và số đang đặt không thay đổi.');}break;
 case'reject':if(role==='manager'&&q?.status==='Pending')modal('Từ chối đề xuất '+id,`<form id="reject-form" data-id="${id}"><label>Lý do từ chối *<textarea name="reason" required placeholder="Nêu rõ nội dung Planner cần xem lại"></textarea></label><div id="dialog-error" class="error" role="alert"></div><div class="form-footer">${btn('Quay lại','close','quiet')}<button type="submit" class="danger">Xác nhận từ chối</button></div></form>`);break;
 case'copy':if(role==='planner'&&q?.status==='Rejected'){const lines=q.lines.map(l=>{const p=product(l.sku),offer=p.offers.find(o=>o.supplier===l.supplier)||p.offers[0];return {...l,name:p.name,unit:p.unit,supplier:offer.supplier,price:offer.price,suggested:suggested(p)};});makeDraft(lines,q.id);}break;
 case'ai-fail':aiFailed=!aiFailed;render();break;
 case'ai':if(requireDraft(q)){const result=$('#ai-result');if(aiFailed){result.innerHTML=notice('Trợ lý không khả dụng','Tiếp tục chỉnh bản nháp bằng biểu mẫu. Không có dữ liệu nào bị mất.','warn');break;}const update=$('#ai-request').value==='suggest';result.innerHTML=notice('Kết quả mô phỏng · Chưa áp dụng',q.lines.map(l=>{const p=product(l.sku);return `${esc(p.name)}: ${!p.complete?'thiếu lịch sử, không khuyến nghị.':`Position ${position(p)}, mục tiêu ${p.target} → gợi ý ${suggested(p)} ${esc(p.unit)}.`}`;}).join('<br>'))+(update?btn('Áp dụng gợi ý vào bản nháp','apply-ai','quiet',`data-id="${id}"`):'');}break;
 case'apply-ai':if(requireDraft(q)){q.lines.forEach(l=>{const p=product(l.sku);if(p.complete&&suggested(p)>0)l.qty=suggested(p);l.suggested=suggested(p);});history(q,'áp dụng gợi ý AI mô phỏng vào bản nháp');save();render();}break;
 case'supplier-form':if(role==='planner'){const index=b.dataset.index,s=index==null?null:db.suppliers[Number(index)];modal(s?'Chỉnh sửa nhà cung cấp':'Thêm nhà cung cấp',`<form id="supplier-form" data-index="${index??''}"><label>Tên *<input name="name" required value="${esc(s?.name||'')}"></label><label>Liên hệ *<input name="contact" required value="${esc(s?.contact||'')}"></label><div id="dialog-error" class="error" role="alert"></div><div class="form-footer">${btn('Hủy','close','quiet')}<button type="submit" class="primary">Lưu nhà cung cấp</button></div></form>`);}break;
 case'cancel-record':if(role==='planner'&&['orders','backorders'].includes(b.dataset.kind)){const kind=b.dataset.kind,r=db[kind].find(r=>r.id===id);if(!r||remaining(r)<=0)return;modal('Hủy phần còn lại · '+id,`<form id="cancel-form" data-kind="${kind}" data-id="${id}"><p>Còn ${remaining(r)} ${esc(product(r.sku).unit)}. Hủy không thay đổi tồn hiện có.</p><label>Số lượng hủy *<input name="qty" type="number" min="1" max="${remaining(r)}" step="1" required value="${remaining(r)}"></label><label>Lý do *<textarea name="reason" required></textarea></label><div id="dialog-error" class="error" role="alert"></div><div class="form-footer">${btn('Quay lại','close','quiet')}<button type="submit" class="danger">Xác nhận hủy</button></div></form>`);}break;
 }
}
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(b&&!b.disabled)handleAction(b);});
document.addEventListener('input',e=>{if(e.target.id==='search'){const caret=e.target.selectionStart;search=e.target.value;render();$('#search').focus();$('#search').setSelectionRange(caret,caret);}});
document.addEventListener('change',e=>{
 if(isRendering)return;
 const el=e.target;
 if(!el.dataset.edit&&!['demand-sku','record-sku'].includes(el.id))return;
 if(!syncIdentity()||currentUser.must_change_password){render();return;}
 if(el.id==='demand-sku'){demandSku=el.value;render();return;}
 if(el.id==='record-sku'){const p=product(el.value);if($('#record-party'))$('#record-party').innerHTML=options(p.offers.map(o=>[o.supplier,o.supplier]),'');return;}
 if(el.dataset.edit){const q=qById(el.dataset.id);if(!requireDraft(q))return;const field=el.dataset.edit,line=q.lines[Number(el.dataset.index)];if(field==='budget'){const v=Number(el.value);if(!Number.isFinite(v)||v<0||el.value===''){el.setCustomValidity('Ngân sách phải là số không âm.');el.reportValidity();return;}q.budget=v;}else if(field==='qty'){const v=Number(el.value);if(!Number.isInteger(v)||v<1){el.setCustomValidity('Số lượng phải là số nguyên lớn hơn 0.');el.reportValidity();return;}line.qty=v;}else if(field==='supplier'){const offer=product(line.sku).offers.find(o=>o.supplier===el.value);if(!offer)return;line.supplier=offer.supplier;line.price=offer.price;}el.setCustomValidity('');history(q,'cập nhật '+({budget:'ngân sách',qty:'số lượng',supplier:'nhà cung cấp'}[field]));save();render();}
});
document.addEventListener('submit',async e=>{
 e.preventDefault();const f=e.target,data=new FormData(f),str=k=>String(data.get(k)||'').trim(),qty=Number(data.get('qty'));const error=text=>{const target=f.querySelector('[role="alert"]');if(target)target.textContent=text;};
 if(['login-form','password-form','user-form','reset-password-form','user-filter'].includes(f.id)){
  const submit=f.querySelector('button[type=submit]');if(submit)submit.disabled=true;
  try{
   if(f.id==='login-form'){const user=await A.login(str('username'),String(data.get('password')||''));syncIdentity();go(user.must_change_password?'password':menus[user.role][0]);}
   else if(!syncIdentity()){render();return;}
   else if(f.id==='password-form'){if(data.get('new_password')!==data.get('confirmation'))throw Error('Xác nhận mật khẩu không khớp.');await A.changePassword(String(data.get('old_password')),String(data.get('new_password')));syncIdentity();go(menus[role][0]);toast('Đã đổi mật khẩu.');}
   else if(f.id==='user-form'){const self=f.dataset.id===currentUser.id;await A.saveUser(f.dataset.id,{username:str('username'),full_name:str('full_name'),role:self?'admin':str('role'),is_active:self||str('is_active')==='true',password:String(data.get('password')||'')});go('users');toast('Đã lưu tài khoản.');}
   else if(f.id==='reset-password-form'){await A.resetPassword(f.dataset.id,String(data.get('password')));close();render();toast('Đã cấp mật khẩu tạm.');}
   else {if(role!=='admin')return;accountSearch=str('search');accountRole=str('role');accountStatus=str('status');render();}
  }catch(err){error(err.message);}finally{if(submit?.isConnected)submit.disabled=false;}
  return;
 }
 if(!syncIdentity()||currentUser.must_change_password){render();return;}
 if(f.id==='stock-form'){
  if(role!=='staff')return;const p=product(f.dataset.sku),type=f.dataset.type,count=type==='count',receipt=type==='receipt';const r=receipt?db.orders.find(r=>r.id===str('record')):db.backorders.find(r=>r.id===str('record'));
  if(!Number.isInteger(qty)||qty<(count?0:1))return error('Nhập số nguyên '+(count?'không âm.':'lớn hơn 0.'));
  if(!str('reason'))return error('Vui lòng nhập lý do.');
  if(receipt&&(!r||r.sku!==p.id))return error('Chọn đơn đã đặt của đúng sản phẩm.');
  if(!count&&!receipt&&qty>p.hand)return error(`Không đủ tồn: chỉ có ${p.hand} ${p.unit}.`);
  if(!count&&r&&(r.sku!==p.id||qty>remaining(r)))return error(`Vượt số lượng còn lại: ${remaining(r)} ${p.unit}.`);
  const before=p.hand;p.hand=count?qty:receipt?p.hand+qty:p.hand-qty;
  if(!count&&r){r.done+=qty;history(r,`${receipt?'nhận':'giao'} ${qty} ${p.unit} · ${str('reason')}`);}
  if(!count&&!receipt)db.sales.push({date:TODAY,sku:p.id,qty,kind:r?'Giao backorder':'Bán hàng',ref:r?.id||'BH-'+(db.sales.length+1)});
  db.history.push({sku:p.id,text:`${count?'Kiểm kê':receipt?'Nhận hàng':'Xuất bán'} ${qty} ${p.unit}${r&&!count?' · '+r.id:''} · Tồn ${before} → ${p.hand}`,time:stamp(),actor:actorName(),actor_id:currentUser.id,reason:str('reason')});save();go('product/'+p.id);toast(`Đã lưu. Tồn hiện có: ${p.hand} ${p.unit}.`);
 }else if(f.id==='reject-form'){
  const q=qById(f.dataset.id);if(role!=='manager'||q?.status!=='Pending')return;if(!str('reason'))return error('Bắt buộc nhập lý do từ chối.');q.status='Rejected';q.reason=str('reason');history(q,'từ chối: '+q.reason);save();close();render();toast('Đã lưu quyết định từ chối.');
 }else if(f.id==='add-line-form'){
  const q=qById(f.dataset.id),p=product(str('sku'));if(!requireDraft(q)||!p||q.lines.some(l=>l.sku===p.id))return;q.lines.push(currentLine(p));history(q,'thêm '+p.id);save();close();render();
 }else if(f.id==='product-form'){
  if(role!=='planner')return;const id=f.dataset.id,p=product(id),sku=str('sku');if(!p&&product(sku))return error('SKU đã tồn tại.');if(!str('name')||!str('unit'))return error('Nhập tên và đơn vị.');const vals=['lead','safety','target'].map(k=>Number(data.get(k)));if(vals.some(v=>!Number.isInteger(v)||v<0))return error('Chính sách phải là số nguyên không âm.');const offers=db.suppliers.flatMap((s,i)=>data.has('offer-'+i)?[{supplier:s.name,price:Number(data.get('price-'+i))}]:[]);if(!offers.length||offers.some(o=>!Number.isFinite(o.price)||o.price<0))return error('Chọn ít nhất một nhà cung cấp với giá không âm.');const fields={id:sku,name:str('name'),unit:str('unit'),lead:vals[0],safety:vals[1],target:vals[2],offers};if(p)Object.assign(p,fields);else db.products.push({...fields,hand:0,complete:false});save();go('catalog');toast('Đã lưu sản phẩm. Lịch sử đề xuất giữ nguyên.');
 }else if(f.id==='supplier-form'){
  if(role!=='planner')return;const index=f.dataset.index,old=index===''?null:db.suppliers[Number(index)],name=str('name');if(!name||!str('contact'))return error('Nhập tên và liên hệ.');if(db.suppliers.some(s=>s!==old&&s.name.toLowerCase()===name.toLowerCase()))return error('Nhà cung cấp đã tồn tại.');if(old){db.products.forEach(p=>p.offers.forEach(o=>{if(o.supplier===old.name)o.supplier=name;}));Object.assign(old,{name,contact:str('contact')});}else db.suppliers.push({name,contact:str('contact')});save();close();render();toast('Đã lưu nhà cung cấp.');
 }else if(f.id==='record-form'){
  if(role!=='planner')return;const kind=f.dataset.kind,p=product(str('sku'));if(!Number.isInteger(qty)||qty<1||!str('party')||!str('reason'))return error('Nhập đối tác, số lượng nguyên dương và lý do.');if(kind==='orders'&&!p.offers.some(o=>o.supplier===str('party')))return error('Chọn nhà cung cấp của sản phẩm.');let n=27;const prefix=kind==='orders'?'PO-':'BO-';while(db[kind].some(r=>r.id===prefix+n))n++;const r={id:prefix+n,sku:p.id,party:str('party'),qty,done:0,cancelled:0,history:[]};history(r,`ghi nhận ${qty} ${p.unit} · ${str('date')} · ${str('reason')}`);db[kind].push(r);save();go('record/'+kind+'/'+r.id);toast('Đã ghi nhận. Tồn hiện có không thay đổi.');
 }else if(f.id==='cancel-form'){
  if(role!=='planner')return;const r=db[f.dataset.kind].find(r=>r.id===f.dataset.id);if(!r||!Number.isInteger(qty)||qty<1||qty>remaining(r))return error('Số lượng hủy phải nằm trong phần chưa hoàn tất.');if(!str('reason'))return error('Bắt buộc nhập lý do hủy.');r.cancelled+=qty;history(r,`hủy ${qty} ${product(r.sku).unit} · ${str('reason')}`);save();close();render();toast('Đã hủy phần chưa hoàn tất. Tồn hiện có giữ nguyên.');
 }
});
window.addEventListener('hashchange',()=>{render();window.scrollTo(0,0);});
window.addEventListener('storage',e=>{if(e.key==='stockmate-accounts-v1'&&currentUser){close();render();}});
window.addEventListener('focus',()=>{if(!A.current())render();});
A.ready.then(()=>render()).catch(err=>{$('#app').textContent=err.message;});
})();
